/**
 * @file audio.h
 * @brief Sound effects and music through one software mixer
 *
 * Sounds are mono 16-bit samples at MIXER_RATE, whether decoded from a WAV
 * file (load_sound converts any format SDL can read) or generated by the game
 * (set_sound copies them). Music comes from a callback the game provides, so
 * it can be a sequencer or streamed audio. Mixing runs in the audio thread;
 * functions here take the device lock when they touch shared state.
 *
 * With no sound device the context still works: nothing is heard, and
 * audio_render can be driven by hand, which is how the tests use it.
 */

#ifndef CORE_AUDIO_AUDIO_H_
#define CORE_AUDIO_AUDIO_H_

#include <SDL.h>
#include <stdbool.h>
#include <stdint.h>

#include "mixer.h"

/** Fills `out` with `frames` mono samples of music scaled by `gain`. */
typedef void (*music_source_fn)(void* user, int16_t* out, int frames,
                                float gain);

typedef struct {
  mixer_t mixer;
  sample_t* sounds;
  int16_t** sound_data;
  int max_sounds;
  music_source_fn music;
  void* music_user;
  float music_gain;
  bool music_enabled;
  bool sound_enabled;
  float volume;  // 0..1
  SDL_AudioDeviceID device;
} audio_context_t, *audio_context_ptr;

/**
 * @brief Open the sound device and make a context for `max_sounds` sounds
 * @param volume Master volume, 0 to 128
 * @return The context, or NULL when memory runs out; a missing device is not
 *         an error
 */
audio_context_ptr init_audio_context(int max_sounds, int volume);

/** Decodes `base_path`/`sound_file` into slot `index`. */
bool load_sound(audio_context_ptr audio, int index, const char* base_path,
                const char* sound_file);

/** Copies `frames` mono samples at MIXER_RATE into slot `index`. */
bool set_sound(audio_context_ptr audio, int index, const int16_t* data,
               int frames);

/** Length of a loaded sound in frames; 0 if the slot is empty. */
int sound_length(const audio_context_ptr audio, int index);

void play_sound(audio_context_ptr audio, int index);
void play_sound_at_volume(audio_context_ptr audio, int index, float volume);

/** Master volume, 0 to 128. */
void set_audio_volume(audio_context_ptr audio, int volume);

void set_sound_enabled(audio_context_ptr audio, bool enabled);

void set_music_source(audio_context_ptr audio, music_source_fn source,
                      void* user);
void set_music_gain(audio_context_ptr audio, float gain);
void set_music_enabled(audio_context_ptr audio, bool enabled);

/** What the device callback does: mixes sounds and music into `out`. */
void audio_render(audio_context_ptr audio, int16_t* out, int frames);

void terminate_audio_context(audio_context_ptr audio);

#endif  // CORE_AUDIO_AUDIO_H_
